-- Migration 0032_workspace_deletion: generated by drizzle-kit (the table, column and index), policy, grants and functions hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #302)
-- Workspace deletion (#302, part 2 of #31; docs/engineering/data-lifecycle.md):
--   * legal_hold_invoice: global (GLOBAL_TABLES), content-free statutory copy of an erased
--     workspace's issued, paid and void SaaS invoices. No FK, so it outlives the purge. Write-once:
--     the app and clerk roles may not UPDATE, DELETE or TRUNCATE it.
--   * deletion_tombstone.receipt: the signed deletion receipt (hashes, timestamps, counts).
--   * deletion_job_workspace_active_uq: one pending, scheduled or running workspace deletion per
--     workspace.
--   * owner_definer_read on deletion_job and app_deletion_due_jobs(now): ids of workspace deletions
--     whose cool-off has ended (or that a crash left scheduled or running), for the hourly
--     `system.deletion.tick` job.
--   * app_finalize_workspace_deletion(workspace, receipt_hash, receipt): the final erase step, for
--     the pinned workspace only. In one transaction it writes the tombstone, purges the workspace's
--     audit_event, ai_call and usage_period_summary rows (which the app role cannot delete) and
--     deletes the organization row, which cascades every remaining tenant row (deletion_job and the
--     destroyed workspace_key included). Refuses unless the workspace is soft-deleted and its key
--     destroyed; a second call after the tombstone exists does nothing.
-- New table, column, index, policy, grants and functions only: nothing existing is altered or dropped.
CREATE TABLE "legal_hold_invoice" (
	"invoice_id" uuid PRIMARY KEY NOT NULL,
	"workspace_id" uuid NOT NULL,
	"number" text NOT NULL,
	"series" text NOT NULL,
	"fy" text NOT NULL,
	"status" text NOT NULL,
	"issue_date" date NOT NULL,
	"period_start" date,
	"period_end" date,
	"place_of_supply_state_code" text NOT NULL,
	"sac" text NOT NULL,
	"taxable_paise" bigint NOT NULL,
	"cgst_paise" bigint NOT NULL,
	"sgst_paise" bigint NOT NULL,
	"igst_paise" bigint NOT NULL,
	"total_paise" bigint NOT NULL,
	"currency" text NOT NULL,
	"supplier_gstin" text,
	"supplier_state_code" text NOT NULL,
	"recipient_gstin" text,
	"recipient_state_code" text NOT NULL,
	"legal_hold" boolean DEFAULT true NOT NULL,
	"retain_until" date NOT NULL,
	"retained_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "legal_hold_invoice_hold_chk" CHECK (legal_hold = true),
	CONSTRAINT "legal_hold_invoice_status_chk" CHECK (status in ('issued', 'paid', 'void'))
);
--> statement-breakpoint
ALTER TABLE "deletion_tombstone" ADD COLUMN "receipt" jsonb DEFAULT '{}'::jsonb NOT NULL;--> statement-breakpoint
CREATE INDEX "legal_hold_invoice_workspace_id_idx" ON "legal_hold_invoice" USING btree ("workspace_id");--> statement-breakpoint
CREATE UNIQUE INDEX "deletion_job_workspace_active_uq" ON "deletion_job" USING btree ("workspace_id") WHERE kind = 'workspace' and status in ('pending_cooloff', 'scheduled', 'running');--> statement-breakpoint
REVOKE UPDATE, DELETE, TRUNCATE ON "legal_hold_invoice" FROM causedeck_app, causedeck_clerk, PUBLIC;--> statement-breakpoint
CREATE POLICY "owner_definer_read" ON "deletion_job" AS PERMISSIVE FOR SELECT TO causedeck_owner
  USING (true);--> statement-breakpoint
CREATE FUNCTION app_deletion_due_jobs(p_now timestamptz)
  RETURNS TABLE (id uuid, workspace_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT d.id, d.workspace_id FROM deletion_job d
    WHERE d.kind = 'workspace'
      AND ((d.status = 'pending_cooloff' AND d.cooloff_until <= p_now)
           OR d.status IN ('scheduled', 'running'))
    ORDER BY d.cooloff_until, d.id
    LIMIT 500
  $$;--> statement-breakpoint
CREATE FUNCTION app_finalize_workspace_deletion(p_workspace uuid, p_receipt_hash text, p_receipt jsonb)
  RETURNS boolean
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    BEGIN
      IF p_workspace IS NULL OR p_workspace IS DISTINCT FROM app_current_workspace() THEN
        RAISE EXCEPTION 'finalize is only allowed for the pinned workspace'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      IF EXISTS (SELECT 1 FROM deletion_tombstone t WHERE t.workspace_id = p_workspace) THEN
        RETURN false;
      END IF;
      IF NOT EXISTS (SELECT 1 FROM organization o WHERE o.id = p_workspace AND o.deleted_at IS NOT NULL)
         OR NOT EXISTS (SELECT 1 FROM workspace_key k
                        WHERE k.workspace_id = p_workspace AND k.destroyed_at IS NOT NULL) THEN
        RAISE EXCEPTION 'workspace must be soft-deleted and its key destroyed before finalizing'
          USING ERRCODE = 'object_not_in_prerequisite_state';
      END IF;
      INSERT INTO deletion_tombstone (workspace_id, receipt_hash, receipt)
        VALUES (p_workspace, p_receipt_hash, coalesce(p_receipt, '{}'::jsonb));
      PERFORM set_config('app.audit_retention', 'on', true);
      DELETE FROM audit_event a WHERE a.workspace_id = p_workspace;
      DELETE FROM ai_call c WHERE c.workspace_id = p_workspace;
      PERFORM set_config('app.audit_retention', '', true);
      DELETE FROM usage_period_summary s WHERE s.workspace_id = p_workspace;
      DELETE FROM organization o WHERE o.id = p_workspace;
      RETURN true;
    END
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_deletion_due_jobs(timestamptz), app_finalize_workspace_deletion(uuid, text, jsonb) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_deletion_due_jobs(timestamptz), app_finalize_workspace_deletion(uuid, text, jsonb) TO causedeck_app;
